import { z } from "zod";

/** Resource identifier. Generated by the application as UUID v7; any RFC 9562 UUID is accepted on input. */
export const UuidSchema = z.uuid().describe("UUID (v7 preferred)");
export type Uuid = z.infer<typeof UuidSchema>;

/** URL-safe slug (`engenharia-de-software`). */
export const SlugSchema = z
  .string()
  .min(1)
  .max(64)
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, "Expected a lowercase slug (a-z, 0-9, hyphen)")
  .describe("Lowercase slug");
export type Slug = z.infer<typeof SlugSchema>;

/** LinkedIn URN (`urn:li:person:abc`, `urn:li:share:123`). */
export const LinkedInUrnSchema = z
  .string()
  .regex(/^urn:li:[a-zA-Z]+:[A-Za-z0-9_\-()]+$/, "Expected a LinkedIn URN")
  .describe("LinkedIn URN");
export type LinkedInUrn = z.infer<typeof LinkedInUrnSchema>;

/** Value of the `Idempotency-Key` header on action endpoints (contracts.md §1). */
export const IdempotencyKeySchema = z.uuid().describe("Idempotency-Key header value (UUID)");
export type IdempotencyKey = z.infer<typeof IdempotencyKeySchema>;

/** Optimistic-locking counter exposed by mutable resources (contracts.md §1). */
export const RowVersionSchema = z.int().min(0).describe("Optimistic locking row version");
export type RowVersion = z.infer<typeof RowVersionSchema>;

/** Request id or job id propagated through logs, jobs and audit events. */
export const CorrelationIdSchema = z
  .string()
  .min(1)
  .max(128)
  .describe("Request or job correlation id");
export type CorrelationId = z.infer<typeof CorrelationIdSchema>;

/** Semantic version string (`1.2.0`). */
export const SemverSchema = z
  .string()
  .regex(/^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/, "Expected a semantic version")
  .describe("Semantic version");
export type Semver = z.infer<typeof SemverSchema>;

/** Absolute https URL. External content is only ever fetched over TLS. */
export const HttpsUrlSchema = z
  .url({ protocol: /^https$/, hostname: z.regexes.domain })
  .max(2048)
  .describe("Absolute https URL");
export type HttpsUrl = z.infer<typeof HttpsUrlSchema>;
